// fallow-ignore-file
globalThis.window.NOTO_SANS_MULTILANGUAGE_BASE64 =
  '';

try {
  const font = new FontFace(
    'Noto Sans Multilanguage',
    'url(data:font/ttf;base64,' + globalThis.window.NOTO_SANS_MULTILANGUAGE_BASE64 + ')'
  );
  document.fonts.add(font);
  font.load();
} catch {
  /* font-face failed — system fallback will be used */
}
